// A snapshot of the article list from https://tech-api.katta.cc/v1/articles (2026-11-19), used only when the API
// cannot be reached, so the Learn pages never break. Live data is fetched by articles.js.
export const ARTICLES_FALLBACK = [{"section": "concepts", "slug": "networking-essentials", "group": "core", "no": "CONCEPT // 01", "tag": "FOUNDATIONS", "title": "Networking essentials: how machines reach each other", "dek": "Layers and addresses, one request from tap to answer, TCP or UDP, HTTP, the API styles built on it, pushing updates, phone-to-phone calls, spreading load, layer 4 or 7, distance, and what to do when calls fail."}, {"section": "concepts", "slug": "api-design", "group": "core", "no": "CONCEPT // 02", "tag": "API DESIGN", "title": "API design: getting the interface right", "dek": "The API step of an interview, REST endpoints done well, GraphQL and gRPC, the habits of a clean API, everyday patterns such as pages, filters, retries and versions, and securing it."}, {"section": "concepts", "slug": "data-modelling", "group": "core", "no": "CONCEPT // 03", "tag": "DATA MODELLING", "title": "Data modelling: from requirements to tables", "dek": "What to decide in an interview and when, choosing a database model, keys and relationships, indexes and normalisation, and how to split the data when one database isn't enough."}, {"section": "concepts", "slug": "caching", "group": "core", "no": "CONCEPT // 04", "tag": "CACHING", "title": "Caching: when to add a cache, and how to explain it", "dek": "The method in an interview, where to cache (device, edge, shared cache or in the process), who talks to the cache and when, what to evict when it's full, and what goes wrong."}, {"section": "concepts", "slug": "sharding", "group": "core", "no": "CONCEPT // 05", "tag": "SHARDING", "title": "Sharding: prove you need it, then pick the key", "dek": "When to bring sharding into an answer, partitioning against sharding, shard keys and how to spread them, and what sharding breaks: hot spots, cross-shard queries and transactions."}, {"section": "concepts", "slug": "consistent-hashing", "group": "core", "no": "CONCEPT // 06", "tag": "CONSISTENT HASHING", "title": "Consistent hashing: adding a server without moving everything", "dek": "When to name it and when to explain it, the hash ring step by step, and rings in practice: hot keys, replication and fixed slots."}, {"section": "concepts", "slug": "cap-theorem", "group": "core", "no": "CONCEPT // 07", "tag": "CAP THEOREM", "title": "CAP theorem: what to do when copies can't talk", "dek": "The first question of your non-functional requirements, designing for consistency or for availability, and choosing consistency per feature, with the levels between strong and eventual."}, {"section": "concepts", "slug": "database-indexing", "group": "core", "no": "CONCEPT // 08", "tag": "DATABASE INDEXING", "title": "Database indexing: finding one row among crores", "dek": "Why indexes exist and what they cost, B-trees, LSM trees and hash indexes, and the indexes for special data: geospatial, full-text and more."}, {"section": "concepts", "slug": "numbers-to-know", "group": "core", "no": "CONCEPT // 09", "tag": "NUMBERS TO KNOW", "title": "Numbers to know: what one machine can really do", "dek": "Why old figures mislead, what one machine holds today, what caches, databases, app servers and queues can each take, and how to use the numbers without over-building."}, {"section": "concepts", "slug": "real-time-updates", "group": "patterns", "no": "CONCEPT // 10", "tag": "REAL-TIME UPDATES", "title": "Real-time updates: from one event to every open screen", "dek": "The two hops and when you need them, polling to WebSockets for the first, routing each update to the server holding the connection for the second, the deep dives (reconnection, huge fan-out, ordering), and the whole path at scale."}, {"section": "concepts", "slug": "contention", "group": "patterns", "no": "CONCEPT // 11", "tag": "CONTENTION", "title": "Contention: when everyone wants the last one", "dek": "The last plate of biryani, seat 14C, a shared wallet: when many requests change the same thing at once, code that reads and then writes sells it twice. Here is how to let the database pick one winner, when to lock and when to retry, and what to do about one very hot item."}, {"section": "concepts", "slug": "workflows", "group": "patterns", "no": "CONCEPT // 12", "tag": "WORKFLOWS", "title": "Processes with many steps: state machines and durable workflows", "dek": "Placing an order means charging a card, telling the restaurant, finding a rider and telling the customer, over minutes and across services. Any step can fail or stall. Here is how to keep such a process in a known state, move it on when nothing happens, and survive a crash halfway through."}, {"section": "concepts", "slug": "scaling-reads", "group": "patterns", "no": "CONCEPT // 13", "tag": "SCALING READS", "title": "When reads outnumber writes: layers that take the load", "dek": "Most apps read far more than they write, and a database that copes with the writes can still sink under the reads. Here is how each layer, from the CDN to read replicas, takes its share, how to handle the one key everyone wants, and how to keep users from seeing their own changes vanish."}, {"section": "concepts", "slug": "scaling-writes", "group": "patterns", "no": "CONCEPT // 14", "tag": "SCALING WRITES", "title": "When writes outrun one database: batch, buffer, split", "dek": "Caches and replicas don't help with writes: every write still has to land on the primary. Here is how to make each write cheaper, how a queue turns a spike into a steady load, when to split the data across machines, and what to do about one counter everybody updates."}, {"section": "concepts", "slug": "big-files", "group": "patterns", "no": "CONCEPT // 15", "tag": "LARGE FILES", "title": "Big files: let the bytes go around your servers", "dek": "Photos, videos and exports don't belong in the database or in an API server's memory. Here is how phones upload straight to storage in parts, how the database tracks each file from 'pending' to 'ready', and how downloads stay fast and private."}, {"section": "concepts", "slug": "long-jobs", "group": "patterns", "no": "CONCEPT // 16", "tag": "BACKGROUND JOBS", "title": "Jobs that run for minutes: queues, leases and retries", "dek": "Reports, payouts, exports and video conversions take too long for a request. Here is how a job gets from the API to a worker, how a lease notices a worker that died, how retries and a dead-letter queue keep one bad job from blocking the rest, and how to show progress."}, {"section": "concepts", "slug": "nearby-search", "group": "specialised", "no": "CONCEPT // 17", "tag": "PROXIMITY SEARCH", "title": "Finding what's nearby: cells, trees and distances", "dek": "\"Restaurants that deliver to me\" and \"the nearest free rider\" are questions an ordinary index can't answer well, because nearness is in two dimensions. Here is how geohashes, quadtrees, hexagon grids and R-trees turn them into fast lookups, and how static places differ from riders who move every few seconds."}, {"section": "concepts", "slug": "vector-search", "group": "specialised", "no": "CONCEPT // 18", "tag": "VECTOR SEARCH", "title": "Searching by meaning: embeddings and vector indexes", "dek": "A customer types \"something spicy with cottage cheese\" and expects chilli paneer, though not one word matches. Embeddings turn text and images into points where similar meanings sit close together, and vector indexes find the nearest points among crores in milliseconds, at the price of sometimes missing one."}, {"section": "concepts", "slug": "time-series", "group": "specialised", "no": "CONCEPT // 19", "tag": "TIME SERIES", "title": "Data that arrives by the clock: storing time series", "dek": "Rider speeds every 10 seconds, orders per minute per city, the latency of every API: data that arrives in time order, is read by time range, and matters less as it ages. Here is why general databases struggle with it, how time-series stores compress and expire it, and the one mistake that sinks them: too many series."}, {"section": "concepts", "slug": "sketches", "group": "specialised", "no": "CONCEPT // 20", "tag": "PROBABILISTIC DATA", "title": "Counting the uncountable: sketches for huge data", "dek": "How many different people saw this ad today? Which dishes are trending this hour? What is the p99 latency across 200 servers? Exact answers need memory that grows with the data. Sketches answer in a few kilobytes with a small, known error, and they merge, so each server or hour can keep its own."}, {"section": "concepts", "slug": "change-capture", "group": "specialised", "no": "CONCEPT // 21", "tag": "CHANGE DATA CAPTURE", "title": "Change data capture: turning a database into a stream", "dek": "The search index, the cache and the analytics warehouse all need to know when an order changes. Writing to each from the app breaks the first time a write half-succeeds. Change data capture reads the database's own log instead, so every committed change becomes an event, in order, with nothing missed."}, {"section": "components", "slug": "redis", "group": "tools", "no": "COMPONENT // 01", "tag": "IN-MEMORY STORE", "title": "Redis: one fast server, many data structures", "dek": "Most people meet Redis as a cache, but it is a server of data structures kept in memory: strings, hashes, sorted sets, streams. Here is what each is for, why one command never interrupts another, how it keeps data across a restart, and how a cluster splits keys over machines."}, {"section": "components", "slug": "elasticsearch", "group": "tools", "no": "COMPONENT // 02", "tag": "SEARCH ENGINE", "title": "Elasticsearch: search by words, not by keys", "dek": "Databases find rows by keys and ranges. A search box needs something else: every dish whose name contains these words, ranked by how well it matches, with typos forgiven and results near the user. Here is how an inverted index does that, how to keep it in step with the database, and how to size it."}, {"section": "components", "slug": "kafka-in-practice", "group": "tools", "no": "COMPONENT // 03", "tag": "EVENT LOG", "title": "Kafka in practice: topics, groups and not losing events", "dek": "The stream most systems reach for: how it differs from a queue, choosing keys and partitions, the settings that decide whether an acknowledged event can be lost, how consumer groups share work and rebalance, and what to do when consumers fall behind."}, {"section": "components", "slug": "temporal", "group": "tools", "no": "COMPONENT // 04", "tag": "WORKFLOW ENGINE", "title": "Temporal: workflows that outlive any server", "dek": "Temporal runs ordinary code, such as 'charge, wait for the restaurant, find a rider, refund on failure', as a workflow that survives crashes, deploys and waits of days. Here is who does what in a Temporal setup, the rules workflow code must follow, and when it is worth bringing in."}, {"section": "components", "slug": "api-gateways", "group": "tools", "no": "COMPONENT // 05", "tag": "GATEWAY", "title": "API gateways: the front door, and which one to run", "dek": "What a gateway does before a request reaches your code, how it differs from a load balancer, how rate limiters decide who gets a 429, and how to choose and run one: a managed gateway or self-hosted Kong or Envoy."}, {"section": "components", "slug": "cassandra", "group": "tools", "no": "COMPONENT // 06", "tag": "WIDE-COLUMN DATABASE", "title": "Cassandra: a ring of equals built for writes", "dek": "Cassandra has no leader: every node takes reads and writes, data is copied around a ring, and writes are cheap appends. The catch is that you design one table per question, and deletes behave in ways that surprise people. Here is how to model for it, tune its consistency, and keep it healthy."}, {"section": "components", "slug": "dynamodb", "group": "tools", "no": "COMPONENT // 07", "tag": "MANAGED KEY-VALUE", "title": "DynamoDB: a table you never have to run", "dek": "DynamoDB is a key-value and document store where you never pick a server size, patch an engine or plan a failover. You pay for that with discipline: every query must use a key you designed in advance, and every partition has its own limit. Here is how keys, indexes, capacity and consistency work."}, {"section": "components", "slug": "postgresql", "group": "tools", "no": "COMPONENT // 08", "tag": "RELATIONAL DATABASE", "title": "PostgreSQL: the default database, and how far it stretches", "dek": "PostgreSQL is where most designs should start: transactions, SQL, rich indexes, JSON, geospatial queries and a huge set of extensions. Here is what is going on underneath (row versions, processes, the write-ahead log), how it scales, and where it stops."}, {"section": "components", "slug": "flink", "group": "tools", "no": "COMPONENT // 09", "tag": "STREAM PROCESSOR", "title": "Flink: answers from a stream while it is still flowing", "dek": "Batch jobs answer yesterday's questions. Flink answers them as events arrive: clicks per ad this minute, a card used in two cities within ten minutes, the live ETA of every order. Here is how it handles time, keeps state, and recovers without counting anything twice."}, {"section": "components", "slug": "zookeeper", "group": "tools", "no": "COMPONENT // 10", "tag": "COORDINATION", "title": "ZooKeeper: a small tree that a whole cluster agrees on", "dek": "ZooKeeper stores a little data, configuration, membership, who leads, in a tree of nodes that a small ensemble of servers keeps consistent. Clients can watch nodes and have nodes vanish when they die. From those few pieces come leader election, locks and service discovery."}, {"section": "interview-questions", "slug": "system-design-interviews", "group": "start", "no": "GUIDE // 01", "tag": "INTRODUCTION", "title": "System design interviews: what they test, and how to use this library", "dek": "What happens in a system design interview, what the interviewer is scoring at each level, the kinds of question you'll get, and the order to use this site in."}, {"section": "interview-questions", "slug": "how-to-prepare", "group": "start", "no": "GUIDE // 02", "tag": "PREPARATION", "title": "How to prepare: a plan for the weeks before your interview", "dek": "What to learn first, how to practise so it holds up in the room, how long it takes, and how to tell when you're ready."}, {"section": "interview-questions", "slug": "how-to-answer", "group": "start", "no": "GUIDE // 03", "tag": "METHOD", "title": "How to answer a system design question", "dek": "The same six steps for every question, how long to spend on each, and what the interviewer is listening for at each one. Every question in this section follows them."}, {"section": "interview-questions", "slug": "core-concepts-guide", "group": "start", "no": "GUIDE // 04", "tag": "OVERVIEW", "title": "The core concepts in one page", "dek": "The nine ideas that come up in almost every design: what each one is, when it enters an interview, and what to say about it. Each points to its full article in Concepts."}, {"section": "interview-questions", "slug": "technologies-guide", "group": "start", "no": "GUIDE // 05", "tag": "OVERVIEW", "title": "The technologies worth knowing by name", "dek": "Ten technologies interviewers expect you to recognise: what each is for, when to reach for it, a number to remember, and the catch. Each points to its full article in Components."}, {"section": "interview-questions", "slug": "patterns-guide", "group": "start", "no": "GUIDE // 06", "tag": "OVERVIEW", "title": "The patterns that keep coming back", "dek": "Seven problems that show up in question after question, the usual answer to each, and where you'll meet them in the worked questions. Each points to its full article in Concepts."}, {"section": "interview-questions", "slug": "questions-guide", "group": "start", "no": "GUIDE // 07", "tag": "OVERVIEW", "title": "The questions, and what each one teaches", "dek": "Every worked question on the site, the core challenge it trains, and an order to take them in."}, {"section": "interview-questions", "slug": "url-shortener", "group": "easy", "no": "QUESTION // 01", "tag": "EASY", "title": "Design a URL shortener", "dek": "Zotato sends crores of promo SMS, and every link in them is a short one like zot.to/2Bi. Turn long URLs into short codes, send people to the right page in milliseconds, and never hand out the same code twice."}, {"section": "interview-questions", "slug": "file-sync", "group": "easy", "no": "QUESTION // 02", "tag": "EASY", "title": "Design file storage and sync", "dek": "A bakery owner in Pune fixes a price in the menu PDF on the counter laptop, and the copy on their phone updates a few seconds later. Store people's files safely, keep every device in step, and don't resend a 200 MB video because one second of it changed."}, {"section": "interview-questions", "slug": "restaurants-near-me", "group": "easy", "no": "QUESTION // 03", "tag": "EASY", "title": "Design restaurants near me", "dek": "Open Zotato in Koramangala at 8 pm and the home screen lists restaurants that deliver to you, nearest and best first, in a blink. Find those few hundred among 3 lakh restaurants, thousands of times a second, while kitchens switch on and off all evening."}, {"section": "interview-questions", "slug": "grocery-delivery", "group": "easy", "no": "QUESTION // 04", "tag": "EASY", "title": "Design 10-minute grocery delivery", "dek": "Zotato Minutes promises milk, bread and instant noodles at your door in 10 minutes. That only works if the store is close, the shelf count is right, and nobody sells the last packet twice."}, {"section": "interview-questions", "slug": "ticket-booking", "group": "medium", "no": "QUESTION // 05", "tag": "MEDIUM", "title": "Design match ticket booking", "dek": "Zotato Live opens sales for India vs Pakistan at noon: 1 lakh seats, 50 lakh people. Let them in without falling over, never sell a seat twice, and be fair to the people who aren't bots."}, {"section": "interview-questions", "slug": "photo-sharing", "group": "medium", "no": "QUESTION // 06", "tag": "MEDIUM", "title": "Design photo sharing", "dek": "Zotato Snaps lets diners post photos of what they ate. Each one shows on their profile and on the restaurant's page within seconds, loads fast on a 4G phone, and survives a dish going viral."}, {"section": "interview-questions", "slug": "news-feed", "group": "medium", "no": "QUESTION // 07", "tag": "MEDIUM", "title": "Design a news feed", "dek": "Open Zotato Snaps and the home screen shows new posts from the diners and restaurants you follow, newest first. Build it so it opens instantly, even when a food blogger with 50 lakh followers posts at dinner time."}, {"section": "interview-questions", "slug": "dating-swipes", "group": "medium", "no": "QUESTION // 08", "tag": "MEDIUM", "title": "Design dating app swipes", "dek": "Zotato Date shows people nearby who'd like to go out for dinner, one card at a time. Swipe right for yes, left for no; when two people both say yes, it's a match and both phones buzz at once. Build it for 50 lakh people swiping every evening."}, {"section": "interview-questions", "slug": "coding-judge", "group": "medium", "no": "QUESTION // 09", "tag": "MEDIUM", "title": "Design a coding judge", "dek": "Zotato hires engineers through a 3-hour online contest. A lakh candidates write code in the browser, press Submit, and expect a verdict in seconds: accepted, wrong answer, or too slow. Run strangers' code safely, keep it fair, and survive the rush in the last 15 minutes."}, {"section": "interview-questions", "slug": "chat-app", "group": "medium", "no": "QUESTION // 10", "tag": "MEDIUM", "title": "Design a chat app", "dek": "Zotato Chat lets friends plan dinner together: one-to-one chats and small groups, messages that arrive in a blink, ticks that show they were delivered and read, and nothing lost when a phone drops off the network in a lift."}, {"section": "interview-questions", "slug": "notifications", "group": "medium", "no": "QUESTION // 11", "tag": "MEDIUM", "title": "Design a notification service", "dek": "Zotato sends login OTPs, \"your order is on the way\" updates and a Diwali offer to 5 crore people, by push, SMS and email. Build one service that sends them all, where an OTP is never stuck behind a promotion and nobody gets the same message twice."}, {"section": "interview-questions", "slug": "payments", "group": "medium", "no": "QUESTION // 12", "tag": "MEDIUM", "title": "Design a payment system", "dek": "A customer pays ₹480 for an order by UPI or card, through a payment gateway. Charge them exactly once, never tell them \"failed\" when the money actually went, and keep books that match the bank's to the paisa."}, {"section": "interview-questions", "slug": "job-scheduler", "group": "medium", "no": "QUESTION // 13", "tag": "MEDIUM", "title": "Design a job scheduler", "dek": "\"Ask for a rating an hour after delivery.\" \"Pay every restaurant at 9 pm.\" \"Sync menus every 15 minutes.\" Zotato has crores of jobs that must run at a set time. Run each one close to on time, never lose one, and survive the moment 9 pm arrives."}, {"section": "interview-questions", "slug": "web-crawler", "group": "medium", "no": "QUESTION // 14", "tag": "MEDIUM", "title": "Design a web crawler", "dek": "Zotato wants its food search to know what India's restaurant sites and food blogs say: menus, timings, reviews. That means fetching about 100 crore public pages a month, without ever hammering a small restaurant's website or fetching the same page twice."}, {"section": "interview-questions", "slug": "leaderboard", "group": "medium", "no": "QUESTION // 15", "tag": "MEDIUM", "title": "Design a live leaderboard", "dek": "During an IPL match, Zotato runs a quiz: a question after every few overs, 20 seconds to answer, points for being right. 50 lakh people play, and each wants the top 100 and their own rank, updated seconds after every question."}, {"section": "interview-questions", "slug": "ad-clicks", "group": "medium", "no": "QUESTION // 16", "tag": "MEDIUM", "title": "Design ad click counting", "dek": "Restaurants on Zotato can pay to appear higher in the list. They want to watch views and clicks minute by minute, and they're billed per click. Count crores of events a day fast enough to watch, and exactly enough to bill."}, {"section": "interview-questions", "slug": "key-value-store", "group": "medium", "no": "QUESTION // 17", "tag": "MEDIUM", "title": "Design a distributed key-value store", "dek": "Zotato keeps carts, sessions and app settings for 20 crore accounts: about a terabyte of small values, read lakhs of times a second. Build a store that spreads them over many machines, keeps three copies, and keeps working when a machine dies."}, {"section": "interview-questions", "slug": "shared-editor", "group": "medium", "no": "QUESTION // 18", "tag": "MEDIUM", "title": "Design a shared document editor", "dek": "A restaurant's owner, chef and manager edit their Zotato menu together: one adds a dish while another changes a price, each seeing the other's changes as they type. Build editing where nobody's change is lost, and everyone ends up with the same menu."}, {"section": "interview-questions", "slug": "rider-dispatch", "group": "medium", "no": "QUESTION // 19", "tag": "MEDIUM", "title": "Design rider assignment for food delivery", "dek": "At 8:30 pm Zotato has 3 lakh riders on the road and hundreds of new orders every second. Pick the right rider for each order, so the food is picked up just as it's ready, and never give one rider two orders by mistake."}, {"section": "interview-questions", "slug": "video-streaming", "group": "medium", "no": "QUESTION // 20", "tag": "MEDIUM", "title": "Design video streaming", "dek": "Zotato Recipes lets chefs upload short cooking videos, and 50 lakh people a day watch them on their phones, many on patchy 4G. Get a 10-minute upload ready to watch within minutes, start playback in a couple of seconds, and keep it playing in a lift."}, {"section": "interview-questions", "slug": "menu-search", "group": "medium", "no": "QUESTION // 21", "tag": "MEDIUM", "title": "Design menu search", "dek": "Someone in Pune opens Zotato and types \"panir butter masala\" and expects the right dish from restaurants that are open and deliver to them, in a blink. Search 3 crore dishes across India by their words, cope with Hinglish spellings, and show a price change within a minute."}, {"section": "interview-questions", "slug": "ind-vs-pak", "group": "hard", "no": "QUESTION // 22", "tag": "HARD", "title": "Design live streaming for IND vs PAK", "dek": "On 14 October 2023, 3.5 crore people watched India play Pakistan live on one streaming app, all at the same time. Design the service that sends them the match: the crowd arrives at the toss within minutes, the last over is the busiest moment, and a stall of a few seconds is seen by crores."}, {"section": "real-systems", "slug": "shopify-reservations", "group": "case-studies", "no": "CASE // 01", "tag": "INVENTORY", "title": "Shopify: holding the last unit at checkout, in MySQL instead of Redis", "dek": "While a buyer pays, Shopify holds the units in their cart so nobody else can buy them. It moved those holds out of Redis and into the MySQL database that keeps the stock: one row per unit, SKIP LOCKED to share the rows out, and a slowdown that turned out to be connections, not queries."}, {"section": "real-systems", "slug": "discord-messages", "group": "case-studies", "no": "CASE // 02", "tag": "MESSAGE STORAGE", "title": "Discord: trillions of messages, from Cassandra to ScyllaDB", "dek": "Discord's message store had grown to 177 Cassandra nodes that kept paging the on-call team. The fix was a service in front of the database that merges identical reads, a move to ScyllaDB, and a copy of trillions of messages that took nine days."}, {"section": "real-systems", "slug": "slack-job-queue", "group": "case-studies", "no": "CASE // 03", "tag": "JOB QUEUE", "title": "Slack: putting Kafka in front of a Redis job queue", "dek": "Slack's job queue runs every message post, push notification and link preview, up to 33,000 jobs a second. When Redis filled up during an outage, nothing could be queued or even taken off the queue. The fix wasn't a rewrite: Kafka went in front of Redis as a buffer on disk, with a relay that feeds Redis at a safe rate."}, {"section": "real-systems", "slug": "figma-multiplayer", "group": "case-studies", "no": "CASE // 04", "tag": "COLLABORATION", "title": "Figma: many people editing one design at once", "dek": "Figma lets several people edit the same file live. It skipped operational transforms, the usual approach for shared text, and borrowed simpler ideas from CRDTs, made simpler again because its server decides the order: the last write wins for each property, objects point to their parents, and positions are fractions."}, {"section": "real-systems", "slug": "spotify-data-lake", "group": "case-studies", "no": "CASE // 05", "tag": "DATA LAKE", "title": "Spotify: fast lookups by key, straight from the data lake", "dek": "Spotify keeps petabytes in Bigtable for online use, but exabytes in Parquet files on cloud storage. Random Access Parquet (RAP) adds an index from each key to the exact files and rows, so one user's history can be read from the lake in a few small reads, without copying it into a key-value store."}, {"section": "real-systems", "slug": "meta-zgateway", "group": "case-studies", "no": "CASE // 06", "tag": "PROXY", "title": "Meta ZGateway: a proxy in front of a key-value store", "dek": "ZippyDB, Meta's most used key-value store, had more than a million client hosts, each connecting straight to the database hosts it needed. ZGateway, a stateless proxy tier, cut each host's connections by about 97%, and gave Meta one place to batch requests, merge duplicate reads, shed load per tenant and steer traffic."}];
